CREATE TABLE rooms(id CHAR(36) PRIMARY KEY, name VARCHAR(100) NOT NULL, building VARCHAR(100) NOT NULL, availability_version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE seats(id CHAR(36) PRIMARY KEY,room_id CHAR(36) NOT NULL,code VARCHAR(32) NOT NULL UNIQUE,power_type VARCHAR(30) NOT NULL,FOREIGN KEY(room_id) REFERENCES rooms(id));
CREATE TABLE resource_effects(source_type VARCHAR(30) NOT NULL,source_id CHAR(36) NOT NULL,source_version BIGINT NOT NULL,room_id CHAR(36) NOT NULL,state VARCHAR(20) NOT NULL,start_at TIMESTAMP(6) NOT NULL,reason VARCHAR(500) NOT NULL,PRIMARY KEY(source_type,source_id),FOREIGN KEY(room_id) REFERENCES rooms(id));
CREATE INDEX ix_effect_room ON resource_effects(room_id,state);
CREATE TABLE operations(id CHAR(36) PRIMARY KEY,fingerprint CHAR(64) NOT NULL,result_json JSON NOT NULL);
